exercises.starter:
function namesOfType(roster, type) {
  // return the names of records matching type, in order
}

exercises.solution:
function namesOfType(roster, type) {
  return roster.filter(p => p.type === type).map(p => p.name)
}

exercises.starter:
function strongest(roster) {
  // return the name of the highest-attack record
}

exercises.solution:
function strongest(roster) {
  return roster.reduce((best, p) => (p.attack > best.attack ? p : best)).name
}

exercises.starter:
function countByType(roster) {
  // tally records into a {type: count} object
}

exercises.solution:
function countByType(roster) {
  const counts = {}
  for (const p of roster) {
    counts[p.type] = (counts[p.type] || 0) + 1
  }
  return counts
}

exercises.starter:
function totalAttack(roster) {
  // add up every record's attack
}

exercises.solution:
function totalAttack(roster) {
  return roster.reduce((sum, p) => sum + p.attack, 0)
}

exercises.starter:
function strongestOfType(roster, type) {
  // return the name of the strongest record of the given type
}

exercises.solution:
function strongestOfType(roster, type) {
  return roster
    .filter(p => p.type === type)
    .reduce((best, p) => (p.attack > best.attack ? p : best))
    .name
}
